//! The YARA module catalogue (`data/catalogs/yara/modules.toml`, generated by
//! `cargo xtask codegen` from YARA-X's module reflection: the known modules,
//! their members and why a refused module is refused) and the language data
//! (`data/catalogs/yara/language.toml`): profiles and keywords.
//! Each is read once per process, item by item ([`opentide_core::catalog`]).

use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

pub use crate::catalog_model::{Kind, Member, Overload, ProfileData};

pub struct Catalog {
    /// `(module, path)` to member.
    members: BTreeMap<(String, String), Member>,
    /// YARA-X's default modules opentide supports.
    pub known_modules: BTreeSet<String>,
    /// Why importing a module opentide refuses is refused (`magic`, `vt`, ...).
    pub unsupported: BTreeMap<String, String>,
    pub keywords: BTreeSet<String>,
    pub profiles: BTreeMap<String, ProfileData>,
}

/// What `build.rs` stores (#1743), parsed once at build time: YARA-X's default modules, the
/// modules opentide refuses and why, the members, the keywords, and the profiles.
type Model = (
    Vec<String>,
    BTreeMap<String, String>,
    Vec<Member>,
    Vec<String>,
    BTreeMap<String, ProfileData>,
);

/// The catalogs, pre-parsed by `build.rs` and decoded on first use.
fn model() -> Model {
    opentide_dataset::compiled_value("yara-catalog", opentide_dataset::blob!("yara-catalog"))
}

impl Catalog {
    pub fn cached() -> &'static Catalog {
        static CATALOG: OnceLock<Catalog> = OnceLock::new();
        CATALOG.get_or_init(|| {
            let (modules, unsupported, members, keywords, profiles) = model();
            Catalog {
                members: members
                    .into_iter()
                    .map(|m| ((m.module.clone(), m.path.clone()), m))
                    .collect(),
                known_modules: modules.into_iter().collect(),
                unsupported,
                keywords: keywords.into_iter().collect(),
                profiles,
            }
        })
    }

    pub fn member(&self, module: &str, path: &str) -> Option<&Member> {
        self.members.get(&(module.to_string(), path.to_string()))
    }

    /// The members directly under `path` (`""` is the module itself).
    pub fn children<'a>(
        &'a self,
        module: &'a str,
        path: &'a str,
    ) -> impl Iterator<Item = &'a Member> + 'a {
        self.members
            .range((module.to_string(), String::new())..)
            .take_while(move |((m, _), _)| m == module)
            .map(|(_, member)| member)
            .filter(move |member| parent_of(&member.path) == path)
    }
}

/// `sections[].name` -> `sections[]`; `imphash` -> `""`.
pub fn parent_of(path: &str) -> &str {
    path.rsplit_once('.').map_or("", |(parent, _)| parent)
}

/// The last segment of a path, without `[]` or `{}`.
pub fn leaf_name(path: &str) -> &str {
    let leaf = path.rsplit('.').next().unwrap_or(path);
    leaf.trim_end_matches("[]").trim_end_matches("{}")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Deserialize;

    fn modules_toml() -> &'static str {
        opentide_dataset::text!("data/catalogs/yara/modules.toml")
    }
    fn language_toml() -> &'static str {
        opentide_dataset::text!("data/catalogs/yara/language.toml")
    }

    #[derive(Deserialize)]
    struct ModulesMeta {
        modules: Vec<String>,
    }

    #[derive(Deserialize)]
    struct ModulesFile {
        meta: ModulesMeta,
        unsupported: BTreeMap<String, String>,
        member: Vec<Member>,
    }

    #[derive(Deserialize)]
    struct LanguageFile {
        keywords: Vec<String>,
        profile: BTreeMap<String, ProfileData>,
    }

    #[test]
    fn catalog_loads_yara_xs_default_modules() {
        let c = Catalog::cached();
        for module in ["pe", "elf", "lnk", "crx", "zip", "console", "string"] {
            assert!(c.known_modules.contains(module), "{module}");
        }
        // `vt` is excluded and `magic` is no YARA-X default: both are
        // refused, each with its reason.
        for module in ["vt", "magic"] {
            assert!(!c.known_modules.contains(module), "{module}");
            assert!(c.unsupported.contains_key(module), "{module}");
        }
        let name = c
            .member("pe", "sections[].name")
            .expect("pe.sections[].name");
        assert_eq!(name.kind, Kind::String);
        let exports = c.member("pe", "exports").expect("pe.exports");
        assert!(
            exports
                .overloads
                .iter()
                .any(|o| o.args == "s" && o.ret == "boolean")
        );
        assert_eq!(
            c.member("pe", "is_signed").map(|m| m.kind),
            Some(Kind::Boolean)
        );
        assert!(c.children("pe", "").any(|m| m.path == "number_of_sections"));
        assert!(c.keywords.contains("condition"));
        assert_eq!(c.profiles["bitdefender"].max_characters, Some(30000));
    }

    /// What the build stored is the whole-file parse, field for field (#1743).
    #[test]
    fn the_stored_catalogs_are_the_whole_files() {
        let (modules, unsupported, members, keywords, profiles) = super::model();
        let whole: ModulesFile = toml::from_str(modules_toml()).expect("modules.toml");
        assert_eq!(modules, whole.meta.modules);
        assert_eq!(unsupported, whole.unsupported);
        assert_eq!(format!("{members:?}"), format!("{:?}", whole.member));
        let whole: LanguageFile = toml::from_str(language_toml()).expect("language.toml");
        assert_eq!(keywords, whole.keywords);
        assert_eq!(format!("{profiles:?}"), format!("{:?}", whole.profile));
    }

    /// `yara_x_syntax` is `allowed` or `refused`; a misspelt value is an
    /// error, not a profile that silently refuses.
    #[test]
    fn yara_x_syntax_takes_only_its_two_values() {
        let profile = |value: &str| {
            toml::from_str::<ProfileData>(&format!(
                "yara_x_syntax = \"{value}\"\nascii_only = false\n\
                 confirmed_modules = []\nrecommended_meta = []\n"
            ))
        };
        assert_eq!(
            profile("allowed").expect("allowed").yara_x_syntax,
            crate::YaraXSyntax::Allowed
        );
        assert_eq!(
            profile("refused").expect("refused").yara_x_syntax,
            crate::YaraXSyntax::Refused
        );
        assert!(profile("allow").is_err());
        assert!(profile("Allowed").is_err());
        let c = Catalog::cached();
        for name in ["harfanglab", "bitdefender"] {
            assert_eq!(c.profiles[name].yara_x_syntax, crate::YaraXSyntax::Refused);
        }
    }

    /// The checker lets a YARA-X boolean through an argument where a YARA-X
    /// overload takes one (`console.log(pe.is_dll())`). These are every
    /// such place: a sync that drops or adds one changes what is reported.
    #[test]
    fn yara_x_boolean_overloads_beside_number_ones() {
        let mut found = Vec::new();
        for m in Catalog::cached().members.values() {
            let ovs: Vec<&Overload> = m.overloads.iter().collect();
            for o in &ovs {
                for (k, c) in o.args.chars().enumerate() {
                    let number = ovs.iter().any(|x| {
                        x.args.len() == o.args.len()
                            && matches!(x.args.chars().nth(k), Some('i' | 'f'))
                    });
                    if c == 'b' && number {
                        found.push(format!("{}.{}/{}:{k}", m.module, m.path, o.args.len()));
                    }
                }
            }
        }
        found.sort();
        found.dedup();
        assert_eq!(found, ["console.log/1:0", "console.log/2:1"]);
    }

    #[test]
    fn paths_split() {
        assert_eq!(parent_of("sections[].name"), "sections[]");
        assert_eq!(parent_of("imphash"), "");
        assert_eq!(leaf_name("sections[]"), "sections");
    }
}
